UPDATE companies SET description='DDH Ent., Inc. is a family-owned contract manufacturer based in Vista, California. The company was incorporated in 1988 by the DU family, initially serving local clients with cable and wire harness production from a small facility in Vista.

Today DDH provides turnkey contract manufacturing of cable assemblies, wire harnesses, and electromechanical box builds. Its capabilities include high‑voltage EV cable assemblies, medical device cables, power cables using copper and aluminum conductors, flat‑ribbon IDC and flat‑flex cables, custom injection overmolding, and value‑added engineering for component substitution. The firm operates a manufacturing facility in Vista and, through DDH Vietnam and DDH China, offers offshore high‑volume production and global supply‑chain management.

The company serves OEMs in medical devices, telecommunications, military/aerospace, transportation, industrial equipment, power generation, and commercial electric‑vehicle markets.

DDH’s stated mission is to deliver the highest‑quality manufactured products and value‑added services on time at a fair market price. The company emphasizes continual improvement, teamwork, and compliance with AS9100, ISO 9001, ISO 13485, and IATF 16949 standards as its primary differentiators.', certifications=ARRAY['ISO 9001','AS9100','ISO 13485','IATF 16949']::text[], profile='{"capabilities": ["Custom cable assembly", "Wire harness assembly", "High-voltage EV cable assembly", "Medical device cable assembly", "Power cable assembly (copper and aluminum)", "Flat ribbon IDC cable assembly", "Flat flex cable assembly", "Box build / electromechanical assembly", "Custom injection overmolding", "Value-added engineering (component substitution)", "Global supply chain management", "Quick-turn production", "Kan-Ban / JIT stocking programs", "Order fulfillment services", "Engineering services", "100% inspection and test", "100% visual inspection", "JIT delivery (San Diego and Orange Counties)", "Fan assembly", "Custom power cords", "Supplier partnerships", "Bonded inventory management", "Blanket order management", "Vendor managed inventory programs"], "industries": ["Medical devices", "Telecommunications", "Military / Aerospace", "Transportation", "Industrial equipment", "Power generation", "Commercial electric vehicles"], "materials": ["Copper", "Aluminum"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Value-added engineering for cost-saving component alternatives", "Global supply-chain management with bonded inventory and vendor\u2011managed inventory programs", "Quick-turn production and JIT delivery in Southern California", "100% inspection and test on all assemblies", "Manufacturing footprint in both Southern California and Asia (Vietnam, China)"], "facts_used": ["Founded 1988 -> db", "Headquarters Vista, California -> db", "Family-owned (DU family) -> /about-us", "Contract manufacturer of cable/wire harness assemblies -> /", "Certifications ISO 9001, AS9100, ISO 13485, IATF 16949 -> db, /quality", "Industries served: Medical, Telecommunications, Military/Aerospace, Transportation, Industrial, Power, Commercial EV -> /, /about-us", "Facilities in Vista, CA and Asia (Vietnam, China) -> /about-us", "Services: custom cable assemblies, high voltage EV cables, medical cables, power cables, box build, injection overmolding, value-added engineering, global supply chain, quick-turn, JIT, 100% inspection -> /services", "Mission: highest quality products and value-added services on time at fair market value -> /about-us", "Value-added engineering for component alternatives -> /services", "Global supply chain management with bonded inventory, vendor managed inventory -> /services", "Quick-turn production and JIT delivery in San Diego/Orange Counties -> /services", "100% inspection and test -> /services", "Materials: copper and aluminum wires -> / (power cables section)"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Turnkey Contract Manufacturer of Cable, Wire Harness & Mechanical Assemblies", "founded_year": "1988", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='ddh-ent-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Delaney Manufacturing Services operates from Bradenton, Florida, where it has been based since its founding in 1976.

The shop specializes in plastic injection molding and provides a full suite of in-house services that span CAD design, mold tooling, production, assembly, retail packaging, and 3D-printed prototyping. It runs jobs from single-piece prototypes to runs of millions of parts with no minimum or maximum order requirements, and it also manages metal-to-plastic conversion projects for customers looking to reduce cost and weight.

Delaney works with businesses developing new products and with established manufacturers needing production support. Its portfolio covers consumer goods, medical devices, military components, and general industrial parts, and the company says it ships finished goods directly to distributors or retail outlets on behalf of clients.

The company positions its all-in-one model as a way to save customers time and money by eliminating handoffs between design, tooling, molding, and fulfillment. It states that working with inventors and new-product developers helps build its manufacturing base, and it offers a signed unilateral NDA for download to protect intellectual property.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Plastic injection molding", "CAD design", "3D printing / rapid prototyping", "Product assembly", "Retail packaging", "Mold management (customer-owned molds)", "Metal-to-plastic conversion", "Design for manufacturability consulting"], "industries": ["Consumer goods", "Medical devices", "Military / defense", "Industrial equipment", "General manufacturing"], "materials": [], "equipment": [], "volume": "Prototype to millions of parts; no minimum or maximum order quantities", "lead_time": "", "tolerances": "", "built_on": ["All services in-house: CAD design, mold tooling, molding, assembly, packaging", "No minimum or maximum order quantities", "Same-business-day quote response", "Metal-to-plastic conversion expertise", "Signed unilateral NDA available for download"], "facts_used": ["Location: Bradenton, FL -> db, /, /about-us", "Founded 1976 -> db", "50+ years experience -> /, /about-us", "Plastic injection molding focus -> /, /about-us", "In-house CAD design, molding, assembly, packaging -> /about-us", "No minimums or maximums -> /, /about-us", "Global clients -> /, /about-us", "Industries: consumer, medical, military, industrial -> /about-us", "Metal-to-plastic conversion -> /", "3D printing for prototyping -> /about-us", "NDA available -> /", "Same-day quote response -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "As a leading injection molding company, we take immense pride in delivering products that are not only of the highest quality but also embody our dedication to exceptional customer service.", "founded_ye