UPDATE companies SET description='Dakota Emporium Trading Post has operated from Fort Pierre, South Dakota since 1926. The business occupies a storefront and is run by proprietor Mike, who also travels to regional powwows with inventory.

The trading post stocks a wide range of Native American craft supplies, including seed beads, regalia components, jewelry findings, drum-making materials, tanned hides, quillwork, and botanicals. It also carries finished Native-made jewelry and artwork. Operations are centered on a single retail location, with additional sales conducted at events across the region.

The store serves Native American artisans, powwow dancers, cultural practitioners, and hobbyists seeking authentic materials for traditional and contemporary craftwork. Customers include individuals preparing regalia for ceremonies, as well as collectors of Native-made artwork.

The company emphasizes personal service and competitive pricing, with the proprietor known for traveling to meet customers at powwows and other gatherings.', certifications=ARRAY[]::text[], profile='{"capabilities": [], "industries": ["Native American arts and crafts", "Cultural and regalia supplies", "Powwow and ceremonial materials"], "materials": ["Beads", "Hides", "Quills", "Botanicals", "Regalia supplies", "Jewelry findings", "Drum-making materials"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded 1926 -> db", "Headquarters Fort Pierre, South Dakota -> db", "Address 119 Deadwood St, PO Box 398, Fort Pierre, SD 57532 -> homepage", "Proprietor Mike mentioned in reviews -> homepage", "Offers beads, regalia supplies, jewelry, drum making supplies, hides -> homepage", "Carries Native-made jewelry, quill and bead work, botanicals -> homepage", "Sells at powwows (per reviews) -> homepage"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "We offer an extensive selection of beads and regalia supplies, jewelry, drum making supplies, and hides.", "founded_year": "1926", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='dakota-emporium-trading-post' AND approved AND profile IS NULL;
UPDATE companies SET description='Dakota Fabrication Inc. was incorporated in February 2006 in Harrisburg, South Dakota, initially specializing in stainless steel pipe fabrication for the ethanol industry. The company has since expanded its capabilities to include carbon steel, aluminum, and alloy piping and structural steel fabrication.

Operating from a 10,000-square-foot shop on two acres near I-29 and I-90, Dakota Fabrication provides ASME Section IV certified pipe welding, orbital welding for high-purity applications, pre-fabricated piping spools, mechanical skid packages, structural and ornamental steel fabrication, and both shop-based and mobile plant maintenance welding. The facility includes lay-down area for project materials and finished items awaiting shipment.

The company serves ethanol plants, power generation facilities, mining operations, and food-grade sectors including dairy, beverage, brewing, distillery, medical, and vaccine production. Past clients include Midwestern Mechanical, Mechanical Solutions LLC, and 9 Clouds, with testimonials citing on-schedule delivery, work quality, and QA/QC performance.

Founded to address the ethanol industry''s need for specialized stainless pipe fabrication, Dakota Fabrication maintains an ISO-like quality program following its 2011 ISO 9001:2008 ANAB registration, emphasizing precision, experience, and responsive on-site service.', certifications=ARRAY['ASME Section IV','ISO 9001:2008']::text[], profile='{"capabilities": ["ASME Section IV certified pipe welding", "Orbital welding (high purity)", "Pre-fabricated piping spools", "Mechanical skid fabrication", "Plant maintenance welding", "Mobile welding services", "Structural steel fabrication", "Custom metal fabrication", "Commercial fabrication", "Ornamental fabrication"], "industries": ["Ethanol", "Power generation", "Mining", "Dairy", "Food grade", "Beverage", "Medical", "Vaccine", "Brewing", "Distillery"], "materials": ["Stainless steel", "Carbon steel", "Alloy piping", "Aluminum"], "equipment": ["Orbital welding system"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["ASME Section IV certified welders", "ISO 9001:2008 ANAB registration (ISO-like quality program maintained)", "10,000+ sq ft facility with two-acre lay-down yard near major interstates", "Mobile welding and on-site plant maintenance services", "Orbital welding system for high-purity sanitary applications"], "facts_used": ["Founded February 2006 -> /about-us", "Facility over 10,000 sq ft, two acres -> /about-us", "ASME Section IV certified welders -> /services", "ISO 9001:2008 ANAB Registered -> /about-us", "Industries: ethanol, power plants, mining, dairy, food grade, beverage, medical, vaccine, brewing, distillery -> /services", "Capabilities: pre-fab piping, orbital welding, mechanical skid fabrication, plant maintenance, mobile welding, misc steel fabrication -> /services", "Materials: stainless steel, carbon steel, alloy, aluminum -> /about-us, /services", "Headquarters Harrisburg, SD -> /about-us", "Testimonials from Midwestern Mechanical, Mechanical Solutions LLC, 9 Clouds -> /"], "company_